{{-- "Did you mean “livewire testing” (2)?" or "Search fewer words: …": the offered searches, each with its count. --}}
<span x-text="correctionLead.before"></span><template x-for="(option, index) in corrections" :key="option.text"><span><span x-show="index > 0" x-text="joiner(index, option)"></span><button type="button" class="text-button" @click="applyCorrection(option)"><span x-text="t('quoted', { text: option.text })"></span><span class="did-you-mean-count" x-show="correctionLead.counts" x-text="` (${option.count})`"></span></button></span></template><span x-text="correctionLead.after"></span>
